WITH with_dims AS (SELECT src.*, b.signup_date, b.age FROM sessions src LEFT JOIN customers b ON src.customer_id = b.id) SELECT CASE WHEN age >= 62 THEN 'PREMIUM' ELSE 'STANDARD' END AS age_tier, DATE_TRUNC('QUARTER', started_at) AS quarter_start, browser, MAX(started_at) AS last_started_at, COUNT_IF(browser = 'Chrome') AS chrome_events, COUNT(*) AS cnt, SIZE(COLLECT_SET(browser)) AS num_browsers, COUNT(DISTINCT customer_id) AS distinct_customer_ids, AVG(age) FILTER (WHERE device = 'mobile') AS mobile_avg_age, DENSE_RANK() OVER (PARTITION BY CASE WHEN age >= 62 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY AVG(age) FILTER (WHERE device = 'mobile') DESC) AS mobile_avg_age_dense_rank FROM with_dims GROUP BY age_tier, quarter_start, browser
